const ORDER = ['low', 'medium', 'max'];
const minT = (a, b) => ORDER[Math.min(ORDER.indexOf(a), ORDER.indexOf(b))];
const fromScore = s => (s >= T.MAX_MIN ? 'max' : s >= T.LOW_MAX ? 'medium' : 'low');

export async function detect() {
  const dpr = window.devicePixelRatio || 1;
  const d = { screen: { w: screen.width, h: screen.height, dpr } };
  d.backingMP = screen.width * dpr * screen.height * dpr / 1e6; // this Mac: 1440x900 @2 = 5.18 MP
  d.cores = navigator.hardwareConcurrency || 0;   // Safari: 4 or 8 only
  d.memGB = navigator.deviceMemory;               // Chromium only; <147: max 8 means >=8
  const uad = navigator.userAgentData;            // Chromium only
  d.mobile = !!(uad && uad.mobile) ||
    (matchMedia('(pointer: coarse)').matches && !matchMedia('(any-pointer: fine)').matches) ||
    (/Macintosh/.test(navigator.userAgent) && navigator.maxTouchPoints > 1); // iPad desktop UA (heuristic)
  const attrs = { powerPreference: POWER, antialias: false, depth: false, stencil: false, alpha: false };
  let gl = document.createElement('canvas').getContext('webgl2', { ...attrs, failIfMajorPerformanceCaveat: true });
  d.caveat = !gl;
  if (!gl) gl = document.createElement('canvas').getContext('webgl2', attrs); // fresh canvas for the retry
  d.webgl2 = !!gl;
  if (!gl) return d;
  const dbg = gl.getExtension('WEBGL_debug_renderer_info'); // deprecated in Firefox -> fall back to RENDERER
  d.renderer = String(gl.getParameter(dbg ? dbg.UNMASKED_RENDERER_WEBGL : gl.RENDERER));
  d.browser = d.renderer === 'Apple GPU' ? 'safari' : gl.getParameter(gl.VENDOR) === 'Mozilla' ? 'firefox' : 'chrome';
  d.timerQuery = !!gl.getExtension('EXT_disjoint_timer_query_webgl2'); // Chrome desktop only
  d.gpu = await webgpuInfo();
  d.cls = classify(d.renderer, d.gpu);
  d.raw = d.caveat || d.cls.id === 'software' ? 0 : await benchmark(gl);
  d.score = 100 * d.raw / REF[d.browser]; // NaN until calibrated
  const lose = gl.getExtension('WEBGL_lose_context');
  if (lose) lose.loseContext(); // free the GPU before import('./game/main')
  return d;
}

async function webgpuInfo() {
  if (!navigator.gpu) return null;
  try {
    const a = await Promise.race([navigator.gpu.requestAdapter({ powerPreference: POWER }),
      new Promise(r => setTimeout(r, 1500, null))]);
    const i = a && a.info; // Chrome: vendor+architecture; Safari 26: vendor-derived; Firefox: ''
    return i ? { vendor: (i.vendor || '').toLowerCase(), arch: i.architecture || '', fallback: !!i.isFallbackAdapter } : null;
  } catch (e) { return null; }
}

export function classify(raw, gpu) {
  const masked = /, or similar$/.test(raw) || raw === 'Apple GPU' || raw === 'Mozilla';
  let s = raw.replace(/, or similar$/, '');
  const m = /^ANGLE [(](.*)[)]$/.exec(s);
  if (m) { const p = m[1].split(', '); s = p.length > 1 ? p[1] : p[0]; }
  s = s.replace(/^ANGLE Metal Renderer: /, '').replace(/ [(]0x[0-9a-fA-F]+[)]/, '')
    .replace(/ Direct3D.*$/, '').split('/PCI')[0].replace(/ OpenGL Engine$/, '').trim();
  const n = s.toLowerCase(), wv = gpu ? gpu.vendor : '';
  const C = (id, why) => ({ id, name: s, masked, why });
  if ((gpu && gpu.fallback) || /swiftshader|llvmpipe|softpipe|basic render driver/.test(n)) return C('software', 'software renderer');
  if (/adreno|mali|powervr|xclipse|videocore|tegra/.test(n)) return C('mobile', 'mobile GPU');
  if (n.startsWith('apple')) {
    if (wv && wv !== 'apple') return C(wv.startsWith('intel') ? 'igpu-old' : 'dgpu-mid', 'Intel-based Mac (WebGPU vendor ' + wv + ')');
    const a = /^apple m([0-9]+)( pro| max| ultra)?$/.exec(n);
    if (a && !masked) return C(a[2] ? 'apple-pro' : 'apple-base', 'Apple M' + a[1] + (a[2] || '') + ' named by the browser');
    return C('apple-masked', 'Apple GPU; model hidden by the browser, decided by benchmark');
  }
  if (n.includes('intel')) {
    if (!masked && /arc[^ ]* [ab][0-9]{3}/.test(n)) return C('dgpu-mid', 'Intel Arc discrete GPU');
    return C(n.includes('arc') ? 'igpu-new' : 'igpu-old', 'Intel integrated graphics');
  }
  if (/nvidia|geforce|quadro|rtx/.test(n)) {
    if (masked) return C('masked', 'NVIDIA (model bucketed by the browser)');
    const x = /(rtx|gtx|gt|mx) ?([0-9]{3,4})/.exec(n);
    if (!x) return C('dgpu-mid', 'NVIDIA GPU');
    const num = +x[2], gen = Math.floor(num / 1000), lvl = num % 100;
    if (x[1] === 'mx' || x[1] === 'gt') return C('dgpu-low', 'entry-level NVIDIA');
    if (x[1] === 'rtx' && ((gen >= 3 && lvl >= 60) || (gen === 2 && lvl >= 70))) return C('dgpu-high', 'NVIDIA ' + x[1].toUpperCase() + ' ' + num);
    return C(num >= 1000 ? 'dgpu-mid' : 'dgpu-low', 'NVIDIA ' + x[1].toUpperCase() + ' ' + num);
  }
  if (/amd|radeon/.test(n)) {
    if (masked) return C('masked', 'AMD (model bucketed by the browser)');
    if (/radeon[(]tm[)] graphics|radeon graphics|vega [0-9]|radeon r[2-7] /.test(n)) return C('igpu-old', 'older AMD APU graphics');
    if (/[0-9]{3}m( |$)/.test(n) && !/rx|pro/.test(n)) return C('igpu-new', 'AMD RDNA APU graphics');
    const x = /rx ?([0-9]{3,4})/.exec(n);
    if (!x) return C('dgpu-mid', 'AMD Radeon GPU');
    const k = +x[1];
    if ((k >= 6700 && k < 7000) || (k >= 7700 && k < 8000) || k >= 9060) return C('dgpu-high', 'Radeon RX ' + k);
    return C(k >= 5000 ? 'dgpu-mid' : 'dgpu-low', 'Radeon RX ' + k);
  }
  return C('unknown', 'unrecognised GPU, decided by benchmark');
}

const VS = `#version 300 es
void main() { vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2)); gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0); }`;
const FS = `#version 300 es
precision highp float;
uniform float uSeed; uniform int uIters; out vec4 o;
void main() {
  vec3 a = vec3(gl_FragCoord.xy * 0.001, uSeed);
  for (int i = 0; i < uIters; i++) {
    a = fract(sin(a.yzx * 1.37 + a.zxy * 0.73 + float(i)) * 43758.5453);
    a += 0.5 * cos(a * 6.2831 + a.zxy);
  }
  o = vec4(a, 1.0);
}`;
const W = 512, H = 512, ITERS = 64;

export async function benchmark(gl, budgetMs = 1500) {
  const sh = (type, src) => { const s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s); return s; };
  const p = gl.createProgram();
  gl.attachShader(p, sh(gl.VERTEX_SHADER, VS)); gl.attachShader(p, sh(gl.FRAGMENT_SHADER, FS)); gl.linkProgram(p);
  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) return NaN;
  gl.useProgram(p);
  const uSeed = gl.getUniformLocation(p, 'uSeed');
  gl.uniform1i(gl.getUniformLocation(p, 'uIters'), ITERS);
  const tex = gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D, tex); gl.texStorage2D(gl.TEXTURE_2D, 1, gl.RGBA8, W, H);
  gl.bindFramebuffer(gl.FRAMEBUFFER, gl.createFramebuffer());
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
  gl.viewport(0, 0, W, H); gl.bindVertexArray(gl.createVertexArray());
  const px = new Uint8Array(4);
  const batch = n => { for (let k = 0; k < n; k++) { gl.uniform1f(uSeed, Math.random()); gl.drawArrays(gl.TRIANGLES, 0, 3); }
    gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px); }; // blocks until the batch is done; no vsync
  const t0 = performance.now(); let n = 1; const per = [];
  batch(1); // shader/pipeline compile + first draw, not measured
  while (performance.now() - t0 < budgetMs && !gl.isContextLost()) {
    const a = performance.now(); batch(n); const dt = performance.now() - a;
    if (dt / n > 50) { per.push(dt / n); break; }          // very slow GPU: stay far below the 2 s TDR
    if (dt < 40) { n = Math.min(n * 2, 1024); continue; }  // grow the batch to >= 40 ms (~1 ms timer precision)
    if (performance.now() - t0 > 300) per.push(dt / n);    // discard compile + GPU clock ramp-up window
    await new Promise(r => setTimeout(r, 0));              // keep the boot UI responsive
  }
  if (!per.length) return NaN;
  per.sort((x, y) => x - y);
  return (W * H * ITERS / 1e6) / per[per.length >> 1];     // raw: Mpix*iter per ms (median)
}

export function recommend(d) {
  if (!d.webgl2) return { preset: 'low', supported: false, text: 'WebGL 2 is not available in this browser, so the game cannot run.' };
  const c = d.cls, s = d.score, ok = Number.isFinite(s), r = [];
  let t;
  switch (c.id) {
    case 'software': case 'mobile': t = 'low'; break;
    case 'apple-base': t = 'medium'; break;                 // M1-M4 base, named (Chrome)
    case 'apple-pro': case 'dgpu-high': t = 'max'; break;   // M-Pro/Max/Ultra, RTX xx60+ (30-series+), RX 6700+
    case 'igpu-old': t = ok && s >= 120 ? 'medium' : 'low'; break; // Intel UHD/Iris Xe, old AMD APUs
    case 'igpu-new': case 'dgpu-low': t = minT('medium', ok ? fromScore(s) : 'low'); break;
    default: t = ok ? fromScore(s) : 'medium';             // apple-masked, masked, dgpu-mid, unknown
  }
  r.push(`GPU: ${c.name || d.renderer} (${c.why})`);
  if (ok) r.push(`benchmark ${Math.round(s)} (100 = Apple M1 7-core in this browser)`);
  if (d.caveat) { t = 'low'; r.push('the browser reports slow or software WebGL'); }
  if (d.mobile) { t = 'low'; r.push('touch device detected; keyboard and mouse are required'); }
  if (d.memGB !== undefined && d.memGB <= 2) { t = 'low'; r.push(`about ${d.memGB} GB RAM`); }
  else if (d.memGB !== undefined && d.memGB <= 4) { t = minT(t, 'medium'); r.push(`about ${d.memGB} GB RAM`); }
  if (d.cores && d.cores < 4) { t = 'low'; r.push(`${d.cores} CPU threads`); }
  const scale = Math.min(1, Math.max(0.4, Math.sqrt(TARGET_MP[t] / d.backingMP)));
  r.push(`display ${d.screen.w}x${d.screen.h} at ${d.screen.dpr}x = ${d.backingMP.toFixed(1)} MP, rendered at ${Math.round(scale * 100)}% (pixel ratio ${(d.screen.dpr * scale).toFixed(2)})`);
  return { preset: t, renderScale: scale, text: `Recommended: ${t.toUpperCase()}. ` + r.join('; ') + '.' };
}

export class FpsMeter {
  constructor(size = 1200) { this.d = new Float32Array(size); this.i = 0; this.n = 0; this.last = -1; }
  reset() { this.i = 0; this.n = 0; this.last = -1; }
  frame(t) { // once per RENDERED frame, with the rAF timestamp
    if (this.last >= 0) { const dt = t - this.last;
      if (dt > 0 && dt < 500) { this.d[this.i] = dt; this.i = (this.i + 1) % this.d.length; if (this.n < this.d.length) this.n++; } }
    this.last = t;
  }
  stats() { // call ~4x per second, not every frame
    const L = this.d.length; let sum = 0, cnt = 0;
    for (let k = 1; k <= this.n && sum < 1000; k++) { sum += this.d[(this.i - k + L) % L]; cnt++; }
    const all = Array.from({ length: this.n }, (_, k) => this.d[(this.i - 1 - k + L) % L]).sort((a, b) => b - a);
    const w = Math.max(1, Math.ceil(this.n * 0.01)); let ws = 0; for (let k = 0; k < w && k < all.length; k++) ws += all[k];
    return { avg: cnt ? cnt * 1000 / sum : 0,             // rolling ~1 s average
             low1: this.n ? 1000 / (ws / w) : 0,          // average of the slowest 1% of recent frames
             p99: this.n ? 1000 / all[w - 1] : 0 };       // 99th-percentile frame time as FPS
  }
}

// getCap(): 30 | 60 | 0 (0 = uncapped = rAF/display rate). tick(t): e.g. timer.update(t);
// step(Math.min(timer.getDelta(), 0.1)); renderer.render(scene, camera)
export function runLoop(tick, getCap, meter) {
  let due = 0, prev = -1, vsync = 1000 / 240; const hist = []; // small tolerance until measured
  function onFrame(t) {
    requestAnimationFrame(onFrame);
    if (prev >= 0) { const x = t - prev;
      if (x > 0 && x < 100) { hist.push(x); if (hist.length === 60) { vsync = hist.slice().sort((a, b) => a - b)[30]; hist.length = 0; } } }
    prev = t; // vsync re-measured every 60 rAFs: ProMotion 120, Safari ~60, Energy Saver ~30
    const cap = getCap();
    if (cap > 0) {
      const interval = 1000 / cap;
      if (due === 0) due = t;
      if (t + vsync * 0.5 < due) return;          // too early: skip this vsync; the canvas keeps the last frame
      due += interval;
      if (t - due > interval) due = t + interval; // after a stall or tab switch: resync, no catch-up burst
    }
    meter.frame(t);
    tick(t);
  }
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) { due = 0; prev = -1; hist.length = 0; meter.reset(); }
  });
  requestAnimationFrame(onFrame);
}
